def load_json(path: Path) -> dict[str, Any]:
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise ValueError(f"Expected JSON object in {path}.")
    return payload


def build_onnx_export_summary(
    onnx_path: Path,
    checkpoint_path: Path,
    checkpoint_payload: dict[str, Any],
    resolved_model_config: ExperimentConfig,
) -> dict[str, Any]:
    raw_config = checkpoint_payload.get("config")
    checkpoint_config = raw_config if isinstance(raw_config, dict) else None
    return {
        "onnx_path": str(onnx_path),
        "checkpoint": str(checkpoint_path),
        "checkpoint_best_stage": checkpoint_payload.get("best_stage"),
        "checkpoint_stage_a_loss": infer_stage_a_loss(
            checkpoint_config=checkpoint_config,
            best_stage=checkpoint_payload.get("best_stage"),
        ),
        "checkpoint_config_raw": checkpoint_config,
        "resolved_model_config": asdict(resolved_model_config),
    }


def onnx_summary_is_current_recipe(summary: dict[str, Any]) -> bool:
    checkpoint_stage_a_loss = summary.get("checkpoint_stage_a_loss")
    if checkpoint_stage_a_loss is not None:
        return checkpoint_stage_a_loss == TRAIN_STAGE_MSE

    raw_config = summary.get("checkpoint_config_raw")
    config_dict = raw_config if isinstance(raw_config, dict) else None
    if config_dict is None:
        legacy_config = summary.get("config")
        config_dict = legacy_config if isinstance(legacy_config, dict) else None
    return infer_stage_a_loss(checkpoint_config=config_dict) == TRAIN_STAGE_MSE


def set_random_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


def resolve_device(config: ExperimentConfig) -> torch.device:
    requested = config.device.lower()
    if requested == "cuda":
        if torch.cuda.is_available():
            return torch.device("cuda")
        if config.allow_cpu_fallback:
            return torch.device("cpu")
        raise RuntimeError("CUDA requested but not available.")
    return torch.device(requested)


def prepare_output_dir(config: ExperimentConfig, smoke: bool) -> Path:
    output_root = REPO_ROOT / config.output_dir
    output_root.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(UTC).strftime("%Y-%m-%d_%H-%M-%S")
    run_name = f"{timestamp}_smoke" if smoke else timestamp
    run_dir = output_root / run_name
    run_dir.mkdir(parents=True, exist_ok=False)
    return run_dir


